# Public-data oracle tests: product PROCESS runner vs the OFFICIAL PROCESS 5.0
# macro on Hayes (2022) book datasets.
#
# The frozen oracle lives in engine/R/tests/reference/public-data-oracle.json
# (generated by the official macro, never by the product runner) and the
# public datasets live outside the tracked tree under
# output/validation-datasets (see REFERENCE.md there). When the datasets are
# absent (e.g. CI without the validation bundle) every test skips; when they
# are present the engine must reproduce the oracle within frozen tolerances.
#
# Engine specs mirror the official SPSS code.sps verbatim: same model number,
# same variables/covariates, same bootstrap seed, and NO centering (the
# official macro runs center=0; the engine spec omits mean centering).

public_data_dir <- Sys.getenv(
  "RESEARCHPATH_PUBLIC_DATA_DIR",
  file.path(Sys.getenv("RESEARCHPATH_PROJECT_ROOT"), "output", "validation-datasets")
)
oracle_path <- file.path(
  Sys.getenv("RESEARCHPATH_PROJECT_ROOT"),
  "engine", "R", "tests", "reference", "public-data-oracle.json"
)
hayes_dir <- file.path(public_data_dir, "hayes", "hayes2022data")

public_oracle <- if (file.exists(oracle_path)) {
  jsonlite::fromJSON(oracle_path, simplifyVector = FALSE)
} else {
  NULL
}
public_tolerance <- public_oracle$provenance$tolerance
public_runs <- public_oracle$runs

nd <- function(id, var, role, type = "continuous") {
  list(id = id, variableId = var, label = id, kind = "observed", role = role, dataType = type)
}
edge <- function(from, to) list(id = paste0("edge_", from, "_", to), from = from, to = to, kind = "regression")
mod <- function(target_edge_id, moderator_id, id = "mod_0", product_term_id = "int_1",
                secondary_moderator_id = NULL, moderator_product_term_id = NULL) {
  entry <- list(id = id, moderatorNodeId = moderator_id, targetEdgeId = target_edge_id,
                productTermId = product_term_id)
  if (!is.null(secondary_moderator_id)) entry$secondaryModeratorNodeId <- secondary_moderator_id
  if (!is.null(moderator_product_term_id)) entry$moderatorProductTermId <- moderator_product_term_id
  entry
}
cov <- function(node_id, outcomes) list(nodeId = node_id, outcomeNodeIds = as.list(outcomes))

estimation_block <- function(bootstrap_enabled, seed) {
  list(
    family = "ols",
    standardErrors = "classical",
    confidenceLevel = 0.95,
    bootstrap = list(
      enabled = bootstrap_enabled, replicates = 5000,
      method = "percentile", seed = seed
    ),
    missing = "complete_cases_per_model",
    centering = list(method = "none", nodeIds = list()),
    reportScale = "unstandardized_primary"
  )
}

base_spec <- function(nodes, edges, moderations = list(), covariates = list(), estimation) {
  list(
    schemaVersion = "1.0.0",
    modelId = "public_data_validation",
    name = "public data oracle validation",
    datasetVersionId = "public_oracle",
    design = list(timeStructure = "cross_sectional", clustering = "none", claimMode = "associational"),
    nodes = nodes,
    edges = edges,
    moderations = moderations,
    covariates = covariates,
    estimation = estimation
  )
}

spec_for <- function(tag) {
  switch(tag,
    pmi_m4 = base_spec(
      nodes = list(nd("x", "cond", "x", "binary"), nd("m1", "pmi", "m"), nd("y", "reaction", "y")),
      edges = list(edge("x", "m1"), edge("m1", "y"), edge("x", "y")),
      estimation = estimation_block(TRUE, 31216)
    ),
    pmi_m6_serial = base_spec(
      nodes = list(
        nd("x", "cond", "x", "binary"), nd("m1", "import", "m"),
        nd("m2", "pmi", "m"), nd("y", "reaction", "y")
      ),
      edges = list(
        edge("x", "m1"), edge("x", "m2"), edge("m1", "m2"),
