dataset_csv <- function(dataset, work_dir) {
  if (identical(dataset, "caskets")) {
    raw <- read.csv(
      file.path(hayes_dir, "caskets", "caskets.csv"),
      check.names = FALSE, fileEncoding = "UTF-8"
    )
    raw$policyc <- raw$policy - 0.5
    raw$kerryc <- raw$kerry - 0.5
    path <- file.path(work_dir, "caskets-centered.csv")
    write.csv(raw, path, row.names = FALSE)
    return(path)
  }
  file.path(hayes_dir, dataset, paste0(dataset, ".csv"))
}

run_engine <- function(tag, spec, data_path, work_dir) {
  input_path <- file.path(work_dir, "input.json")
  output_path <- file.path(work_dir, "output.json")
  writeLines(
    jsonlite::toJSON(
      list(
        modelSpec = spec,
        dataPath = data_path,
        progressPath = file.path(work_dir, "progress.json"),
        cancelPath = file.path(work_dir, "cancel.json"),
        processModelNumber = public_runs[[tag]]$model
      ),
      auto_unbox = TRUE, digits = NA
    ),
    input_path
  )
  runner <- file.path(
    Sys.getenv("RESEARCHPATH_PROJECT_ROOT"), "engine", "R", "run_analysis.R"
  )
  rscript <- file.path(R.home("bin"), "Rscript.exe")
  status <- system2(
    rscript, c("--vanilla", shQuote(runner), shQuote(input_path), shQuote(output_path)),
    stdout = TRUE, stderr = TRUE
  )
  if (!file.exists(output_path)) {
    stop("run_analysis.R failed for ", tag, ": ", paste(status, collapse = "\n"))
  }
  jsonlite::fromJSON(output_path, simplifyVector = FALSE)
}

node_var_map <- function(spec) {
  stats::setNames(
    vapply(spec$nodes, function(node) node$variableId, character(1)),
    vapply(spec$nodes, function(node) node$id, character(1))
  )
}

engine_equation_coeffs <- function(result) {
  stats::setNames(
    lapply(result$equations, function(equation) {
      stats::setNames(
        vapply(equation$coefficients, function(coeff) coeff$estimate, numeric(1)),
        vapply(equation$coefficients, function(coeff) coeff$term, character(1))
      )
    }),
    vapply(result$equations, function(equation) {
      trimws(strsplit(equation$formula, "~", fixed = TRUE)[[1]][1])
    }, character(1))
  )
}

# Oracle equation tables are keyed by outcome variable name; engine equations
# by node id.  Oracle terms use variable names plus the frozen product id.
check_equations <- function(tag, spec, result) {
  actual <- engine_equation_coeffs(result)
  var_by_id <- node_var_map(spec)
  oracle_equations <- public_runs[[tag]]$equations
  for (node in spec$nodes) {
    if (!node$role %in% c("m", "y")) next
    oracle_key <- node$variableId
    oracle_rows <- oracle_equations[[oracle_key]]
    if (is.null(oracle_rows)) stop("oracle missing outcome ", oracle_key, " for ", tag)
    engine_rows <- actual[[node$id]]
    if (is.null(engine_rows)) stop("engine missing outcome ", node$id, " for ", tag)
    for (row in oracle_rows) {
      term <- row$term
      candidates <- if (grepl("^int_[0-9]+$", term)) {
        term
      } else if (identical(term, "constant")) {
        "(Intercept)"
      } else {
        names(var_by_id)[var_by_id == term]
      }
      # The same variableId can back both a moderation node and a covariate
      # node (e.g. disaster_m7: skeptic as W and as covariate). Resolve
      # against the terms actually present in THIS equation first.
      present <- candidates[candidates %in% names(engine_rows)]
      engine_term <- if (length(present) > 0) present[[1]] else if (length(candidates) > 0) candidates[[1]] else term
      expect_true(
        engine_term %in% names(engine_rows),
        info = paste0(tag, ": term ", term, " missing from engine equation for ", oracle_key)
      )
      expect_equal(
        unname(engine_rows[[engine_term]]), row$coeff,
        tolerance = public_tolerance$coefficient,
        info = paste0(tag, ": coefficient ", term, " in ", oracle_key)
      )
    }
  }
}

skip_unless_public_data <- function(dataset) {
  skip_if(
    !dir.exists(hayes_dir) || !file.exists(file.path(hayes_dir, dataset, paste0(dataset, ".csv"))),
    paste0("public validation data absent for ", dataset)
  )
}

# --- Simple mediation, official seed 31216 ----------------------------------

test_that("pmi model 4 reproduces the official macro on Hayes' pmi data", {
  skip_unless_public_data("pmi")
  work <- tempfile("rp-public-pmi4-"); dir.create(work)
  spec <- spec_for("pmi_m4")
  result <- run_engine("pmi_m4", spec, dataset_csv("pmi", work), work)
  check_equations("pmi_m4", spec, result)

  oracle_effects <- public_runs$pmi_m4$effects
  indirect <- Filter(function(effect) effect$type == "indirect", result$effects)[[1]]
  direct <- Filter(function(effect) effect$type == "direct", result$effects)[[1]]
  golden_indirect <- oracle_effects$indirect[[1]]
  expect_equal(unname(indirect$estimate), golden_indirect$effect,
    tolerance = public_tolerance$effect, info = "pmi_m4 indirect effect")
  expect_equal(unname(indirect$standardError), golden_indirect$bootSE,
    tolerance = public_tolerance$bootstrapSE, info = "pmi_m4 indirect bootSE")
  interval <- indirect$confidenceInterval
  expect_equal(interval$lower, golden_indirect$bootLLCI,
    tolerance = public_tolerance$bootstrapInterval, info = "pmi_m4 indirect lower")
  expect_equal(interval$upper, golden_indirect$bootULCI,
    tolerance = public_tolerance$bootstrapInterval, info = "pmi_m4 indirect upper")
  expect_equal(unname(direct$estimate), oracle_effects$direct$effect,
    tolerance = public_tolerance$effect, info = "pmi_m4 direct effect")
})

# --- Serial mediation, official seed 31216 ----------------------------------

test_that("pmi model 6 serial mediation matches the official macro", {
  skip_unless_public_data("pmi")
  work <- tempfile("rp-public-pmi6-"); dir.create(work)
  spec <- spec_for("pmi_m6_serial")
  result <- run_engine("pmi_m6_serial", spec, dataset_csv("pmi", work), work)
  check_equations("pmi_m6_serial", spec, result)

  golden <- public_runs$pmi_m6_serial$effects$indirect
  indirect_by_id <- stats::setNames(
    Filter(function(effect) effect$type == "indirect", result$effects),
    vapply(Filter(function(effect) effect$type == "indirect", result$effects),
      function(effect) effect$id, character(1))
  )
  golden_by_label <- stats::setNames(golden, vapply(golden, function(row) row$label, character(1)))
  mapping <- list(
    "TOTAL" = "effect_total_indirect",
    "Ind1" = "effect_indirect_1",
    "Ind2" = "effect_indirect_2",
    "Ind3" = "effect_indirect_3"
  )
  for (official_label in names(mapping)) {
    golden_row <- golden_by_label[[official_label]]
    effect <- indirect_by_id[[mapping[[official_label]]]]
    expect_equal(unname(effect$estimate), golden_row$effect,
      tolerance = public_tolerance$effect, info = paste0("pmi_m6 ", official_label, " effect"))
    interval <- effect$confidenceInterval
    expect_equal(interval$lower, golden_row$bootLLCI,
      tolerance = public_tolerance$bootstrapInterval, info = paste0("pmi_m6 ", official_label, " lower"))
    expect_equal(interval$upper, golden_row$bootULCI,
      tolerance = public_tolerance$bootstrapInterval, info = paste0("pmi_m6 ", official_label, " upper"))
  }
})

