# --- Model 14 moderated mediation, official seed 42517 ------------------------

test_that("teams model 14 conditional indirect effects and index match the official macro", {
  skip_unless_public_data("teams")
  work <- tempfile("rp-public-teams-"); dir.create(work)
  spec <- spec_for("teams_m14")
  result <- run_engine("teams_m14", spec, dataset_csv("teams", work), work)
  check_equations("teams_m14", spec, result)

  golden_conditional <- public_runs$teams_m14$conditionalIndirect
  conditional <- Filter(function(effect) effect$type == "conditional", result$effects)
  expect_length(conditional, length(golden_conditional))
  for (index in seq_along(golden_conditional)) {
    row <- golden_conditional[[index]]
    # engine rows are ordered by the same 16/50/84 percentile probes
    matched <- conditional[[index]]
    expect_equal(unname(matched$estimate), row$effect,
      tolerance = public_tolerance$effect, info = paste0("teams conditional indirect ", index))
    interval <- matched$confidenceInterval
    expect_equal(interval$lower, row$bootLLCI,
      tolerance = public_tolerance$bootstrapInterval, info = paste0("teams conditional lower ", index))
    expect_equal(interval$upper, row$bootULCI,
      tolerance = public_tolerance$bootstrapInterval, info = paste0("teams conditional upper ", index))
  }
  golden_index <- public_runs$teams_m14$index
  index_effect <- Filter(function(effect) effect$type == "index", result$effects)[[1]]
  expect_equal(unname(index_effect$estimate), golden_index$index,
    tolerance = public_tolerance$effect, info = "teams index of moderated mediation")
})

# --- Model 1 moderation: full conditional-effect surface via JN grid ----------

jn_surface_check <- function(tag, spec, result) {
  # The engine reports a 101-row JN grid; compare the whole conditional-effect
  # surface against the oracle's frozen equation coefficients (exact linear
  # identity) instead of tolerating grid-position mismatch.
  var_by_id <- node_var_map(spec)
  oracle_equation <- public_runs[[tag]]$equations[[
    names(public_runs[[tag]]$equations)[1]
  ]]
  oracle_coeff <- function(term) {
    row <- Filter(function(r) identical(r$term, term), oracle_equation)[[1]]
    if (is.null(row)) return(0)
    row$coeff
  }
  b_x <- oracle_coeff(var_by_id[["x"]])
  b_int <- oracle_coeff("int_1")
  grid <- result$johnsonNeyman$grid
  expect_false(is.null(grid), info = paste0(tag, ": runner must report a JN grid"))
  for (row in grid) {
    expected <- b_x + b_int * row$moderatorValue
    # The official macro prints coefficients to 4 decimals; the frozen oracle
    # therefore carries at most +/-0.00005 rounding per coefficient. The bound
    # below is the propagated rounding error, not a statistical tolerance.
    rounding_bound <- 5e-5 * (1 + abs(row$moderatorValue)) + 1e-6
    expect_equal(
      unname(row$effect), expected,
      tolerance = rounding_bound,
      info = paste0(tag, ": JN grid effect at W=", row$moderatorValue)
    )
  }
  invisible(TRUE)
}

