  spec <- spec_for("disaster_m4")
  result <- run_engine("disaster_m4", spec, dataset_csv("disaster", work), work)
  check_equations("disaster_m4", spec, result)

  golden <- public_runs$disaster_m4$effects
  indirect <- Filter(function(effect) effect$type == "indirect", result$effects)[[1]]
  direct <- Filter(function(effect) effect$type == "direct", result$effects)[[1]]
  golden_indirect <- golden$indirect[[1]]
  expect_equal(unname(indirect$estimate), golden_indirect$effect,
    tolerance = public_tolerance$effect, info = "disaster_m4 indirect effect")
  interval <- indirect$confidenceInterval
  expect_equal(interval$lower, golden_indirect$bootLLCI,
    tolerance = public_tolerance$bootstrapInterval, info = "disaster_m4 indirect lower")
  expect_equal(interval$upper, golden_indirect$bootULCI,
    tolerance = public_tolerance$bootstrapInterval, info = "disaster_m4 indirect upper")
  expect_equal(unname(direct$estimate), golden$direct$effect,
    tolerance = public_tolerance$effect, info = "disaster_m4 direct effect")
})

test_that("disaster model 7 moderated mediation matches the official macro", {
  skip_unless_public_data("disaster")
  work <- tempfile("rp-public-disaster7-"); dir.create(work)
  spec <- spec_for("disaster_m7")
  result <- run_engine("disaster_m7", spec, dataset_csv("disaster", work), work)
  check_equations("disaster_m7", spec, result)

  golden_conditional <- public_runs$disaster_m7$conditionalIndirect
  conditional <- Filter(function(effect) effect$type == "conditional", result$effects)
  expect_length(conditional, length(golden_conditional))
  for (index in seq_along(golden_conditional)) {
    row <- golden_conditional[[index]]
    matched <- conditional[[index]]
    expect_equal(unname(matched$estimate), row$effect,
      tolerance = public_tolerance$effect, info = paste0("disaster_m7 conditional indirect ", index))
    interval <- matched$confidenceInterval
    expect_equal(interval$lower, row$bootLLCI,
      tolerance = public_tolerance$bootstrapInterval, info = paste0("disaster_m7 conditional lower ", index))
    expect_equal(interval$upper, row$bootULCI,
      tolerance = public_tolerance$bootstrapInterval, info = paste0("disaster_m7 conditional upper ", index))
  }
  golden_index <- public_runs$disaster_m7$index
  index_effect <- Filter(function(effect) effect$type == "index", result$effects)[[1]]
  expect_equal(unname(index_effect$estimate), golden_index$index,
    tolerance = public_tolerance$effect, info = "disaster_m7 index of moderated mediation")
})

