# --- Multicategorical X boundary: documented, asserted rejection ---------------

test_that("multicategorical X is rejected with the documented boundary error", {
  skip_unless_public_data("protest")
  work <- tempfile("rp-public-mcx-"); dir.create(work)
  spec <- base_spec(
    nodes = list(
      list(id = "x", variableId = "protest", label = "x", kind = "observed", role = "x",
           dataType = "nominal", encoding = list(method = "treatment")),
      nd("m1", "respappr", "m"), nd("y", "liking", "y")
    ),
    edges = list(edge("x", "m1"), edge("m1", "y"), edge("x", "y")),
    estimation = estimation_block(FALSE, 30217)
  )
  input_path <- file.path(work, "input.json")
  output_path <- file.path(work, "output.json")
  writeLines(
    jsonlite::toJSON(list(
      modelSpec = spec,
      dataPath = file.path(hayes_dir, "protest", "protest.csv"),
      progressPath = file.path(work, "progress.json"),
      cancelPath = file.path(work, "cancel.json"),
      processModelNumber = 4
    ), auto_unbox = TRUE, digits = NA),
    input_path
  )
  runner <- file.path(Sys.getenv("RESEARCHPATH_PROJECT_ROOT"), "engine", "R", "run_analysis.R")
  status <- suppressWarnings(system2(
    file.path(R.home("bin"), "Rscript.exe"),
    c("--vanilla", shQuote(runner), shQuote(input_path), shQuote(output_path)),
    stdout = TRUE, stderr = TRUE
  ))
  expect_false(file.exists(output_path), info = "multicategorical X must not produce a result bundle")
  expect_true(
    any(grepl("PROCESS variable x must be continuous or binary", status)),
    info = paste0("expected the documented boundary error; got: ", paste(status, collapse = "\n"))
  )
})
